CREATE TEMPORARY VIEW feature_scenario_tag_mapping_${grass_region_without_quote} AS
SELECT
    feature_detail,
    max(FILTER(scenario_tags,
            value -> value IN ('DA_Cart Recommendation', 'DA_Cart_Unify', 'DA_Daily Discover', 'DA_Me YMAL','DA_mpp_ymal-order_list','DA_Buy Again (Me Page)',
              'DA_odp_ymal-order_detail', 'DA_Order Successful Recommendation', 'DA_You May Also Like', 'DA_Search', 'DA_Shop YMAL')
    )) AS scenario_tags
from
srdi_mart.dim_sr_data_warehouse_feature_scenario_tag_mapping
WHERE
    grass_region in (${grass_region})
    and local_date = ${local_date}
    and array_join(scenario_tags, '|') like '%DA_%'
GROUP BY feature_detail;

--sql_divide_splitter--

