CREATE TEMPORARY VIEW dwd_fe_join_be_${grass_region_without_quote} AS
SELECT 
    COALESCE(roi_item_type, 'null') AS roi_item_type
    ,CASE WHEN location IS NULL THEN 'null' 
        WHEN location > 120 THEN '>120'
    ELSE CAST(location AS STRING) END AS location
    ,feature_detail
    ,exp_group_ids
    ,CASE WHEN operation = 'impression' THEN price else NULL END AS price
    ,CASE 
        WHEN operation = 'impression' AND is_ads = true THEN rank_score_named['p0_click']
        WHEN operation = 'impression' AND is_ads != true THEN ads_extra_values[1]
    ELSE NULL END AS pctr
    ,CASE 
        WHEN operation = 'impression' AND is_ads = true THEN rank_score_named['p0_order']
        WHEN operation = 'impression' AND is_ads != true THEN ads_extra_values[0]
    ELSE NULL END AS pcr
    ,SUM(CASE WHEN operation = 'impression' THEN operation_cnt else 0 END) AS imp_cnt
    ,SUM(CASE WHEN operation = 'click' THEN operation_cnt else 0 END) AS click_cnt
    ,SUM(CASE WHEN operation = 'cart' THEN operation_cnt else 0 END) AS cart_cnt
    ,SUM(CASE WHEN operation = 'order' THEN operation_cnt else 0 END) AS order_cnt
    ,SUM(CASE WHEN operation = 'order' THEN place_order_gmv else 0 END) AS gmv
    ,SUM(CASE WHEN operation = 'order' THEN place_order_gmv_local else 0 END) AS gmv_local
    ,SUM(CASE 
        WHEN operation = 'impression' AND is_ads = true THEN operation_cnt * rank_score_named['p0_click']
        WHEN operation = 'impression' AND is_ads != true THEN operation_cnt * ads_extra_values[1]
        ELSE 0 END
    ) AS pclick_cnt
    ,SUM(CASE 
        WHEN operation = 'click' AND is_ads = true THEN operation_cnt * rank_score_named['p0_order']
        WHEN operation = 'click' AND is_ads != true THEN operation_cnt * ads_extra_values[0]
        ELSE 0 END
    ) AS porder_cnt_over_click
    ,SUM(CASE 
        WHEN operation = 'cart' AND is_ads = true THEN operation_cnt * rank_score_named['p0_order']
        WHEN operation = 'cart' AND is_ads != true THEN operation_cnt * ads_extra_values[0]
        ELSE 0 END
    ) AS porder_cnt_over_atc
FROM srdi_mart.dwd_sr_data_warehouse_platform_fe_join_be
WHERE local_date = ${local_date}
AND grass_region in (${grass_region})
AND operation IN ('impression', 'click', 'cart', 'order')
AND size(exp_group_ids)>0
GROUP BY 1,2,3,4,5,6,7
UNION ALL
SELECT
    COALESCE(roi_item_type, 'null') AS roi_item_type
    ,CASE WHEN location IS NULL THEN 'null' 
        WHEN location > 120 THEN '>120'
    ELSE CAST(location AS STRING) END AS location
    ,feature_detail
    ,exp_group_ids
    ,NULL AS price
    ,NULL AS pctr
    ,NULL AS pcr
    ,0 AS imp_cnt
    ,0 AS click_cnt
    ,SUM(CASE WHEN operation = 'cart' THEN operation_cnt else 0 END) AS cart_cnt
    ,SUM(CASE WHEN operation = 'order' THEN operation_cnt else 0 END) AS order_cnt
    ,SUM(CASE WHEN operation = 'order' THEN place_order_gmv else 0 END) AS gmv
    ,SUM(CASE WHEN operation = 'order' THEN place_order_gmv_local else 0 END) AS gmv_local
    ,0 AS pclick_cnt
    ,0 AS porder_cnt_over_click
    ,SUM(CASE 
        WHEN operation = 'cart' AND is_ads = true THEN operation_cnt * rank_score_named['p0_order']
        WHEN operation = 'cart' AND is_ads != true THEN operation_cnt * ads_extra_values[0]
        ELSE 0 END
    ) AS porder_cnt_over_atc
FROM srdi_mart.dwd_sr_data_warehouse_platform_fe_join_be_source
WHERE local_date = ${local_date}
AND grass_region in (${grass_region})
AND operation IN ('cart', 'order')
AND size(exp_group_ids)>0
GROUP BY 1,2,3,4,5,6,7;

--sql_divide_splitter--

