CREATE TEMPORARY VIEW dwd_fe_join_be_item_exp_fgroup_ads_${grass_region_without_quote} AS
SELECT 
    a.item_id
    ,exp_group_id
    ,roi_item_type
    ,location
    ,a.feature_group
    ,feature_detail
    ,SUM(broad_order_cnt) AS broad_order_cnt
    ,SUM(broad_gmv_amt_local) AS broad_gmv_amt_local
    ,SUM(revenue_usd) AS revenue_usd
    ,SUM(ads_order_gmv_usd) AS ads_order_gmv_usd
    ,SUM(ads_order_cnt) AS ads_order_cnt
    ,AVG(price_v2) AS price_v2
FROM dwd_fe_join_be_item_exp_fgroup_${grass_region_without_quote} a
LEFT JOIN ads_perf_${grass_region_without_quote} b
ON a.item_id=b.item_id
AND a.feature_group=b.feature_group
GROUP BY GROUPING SETS (
    --Base dimension exp_group_id,location,feature_group. Cube dimension roi_item_type
    (1,2,3,4,5,6), (1,2,4,5,6)
)

UNION ALL
--  __ALL__ metrics
SELECT 
    a.item_id
    ,a.exp_group_id
    ,roi_item_type
    ,location
    ,a.feature_group
    ,feature_detail
    ,SUM(broad_order_cnt) AS broad_order_cnt
    ,SUM(broad_gmv_amt_local) AS broad_gmv_amt_local
    ,SUM(revenue_usd) AS revenue_usd
    ,SUM(ads_order_gmv_usd) AS ads_order_gmv_usd
    ,SUM(ads_order_cnt) AS ads_order_cnt
    ,AVG(price_v2) AS price_v2
FROM dwd_fe_join_be_item_exp_all_fgroup_${grass_region_without_quote} a
LEFT JOIN ads_perf_${grass_region_without_quote} b
ON a.item_id=b.item_id
AND a.feature_group=b.feature_group
GROUP BY 1,2,3,4,5,6;

--sql_divide_splitter--

CREATE TEMPORARY VIEW fe_join_be_item_ads_metrics_${grass_region_without_quote} AS
SELECT 
    exp_group_id
    ,if(roi_item_type IS NULL, '__ALL__', roi_item_type) AS roi_item_type
    ,location
    ,feature_group
    ,feature_detail
    ,SUM(IF(item_id>0, 1, 0)) AS item_cnt
    ,SUM(broad_order_cnt) AS broad_order_cnt
    ,SUM(broad_gmv_amt_local) AS broad_gmv_amt_local
    ,SUM(revenue_usd) AS revenue_usd
    ,SUM(ads_order_gmv_usd) AS ads_order_gmv_usd
    ,SUM(ads_order_cnt) AS ads_order_cnt
    ,AVG(price_v2) AS price_v2
FROM dwd_fe_join_be_item_exp_fgroup_ads_${grass_region_without_quote} a
GROUP BY 1,2,3,4,5;

--sql_divide_splitter--

CREATE TEMPORARY VIEW fe_join_be_metrics_${grass_region_without_quote} AS
SELECT 
    COALESCE(a.exp_group_id,b.exp_group_id) AS exp_group_id
    ,COALESCE(a.roi_item_type,b.roi_item_type) AS roi_item_type
    ,COALESCE(a.location,b.location) AS location
    ,COALESCE(a.feature_group,b.feature_group) AS feature_group
    ,COALESCE(a.feature_detail,b.feature_detail) AS feature_detail
    ,item_cnt
    ,imp_cnt
    ,click_cnt
    ,cart_cnt
    ,order_cnt
    ,gmv
    ,gmv_local
    ,broad_order_cnt
    ,broad_gmv_amt_local
    ,revenue_usd
    ,ads_order_gmv_usd
    ,ads_order_cnt
    ,pclick_cnt
    ,porder_cnt_over_click
    ,porder_cnt_over_atc
    ,avg_imp_price
    ,price_v2
    ,pctr
    ,pcr
    ,pctr_50p
    ,pcr_50p
FROM fe_join_be_avgsum_metrics_coalesced_${grass_region_without_quote} a 
FULL OUTER JOIN fe_join_be_item_ads_metrics_${grass_region_without_quote} b 
ON a.exp_group_id=b.exp_group_id
AND a.roi_item_type=b.roi_item_type
AND a.location=b.location
AND a.feature_detail=b.feature_detail
AND a.feature_group=b.feature_group;

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_platform_exp_location_metrics_1d
PARTITION (grass_region = ${grass_region}, local_date = ${local_date})
SELECT
/*+ REPARTITION(200) */
    exp_group_id
    ,IF(roi_item_type = 'null', NULL, roi_item_type) AS roi_item_type
    ,IF(location = 'null', NULL, location) AS location
    ,feature_group
    ,feature_detail
    ,item_cnt
    ,imp_cnt
    ,click_cnt
    ,cart_cnt
    ,order_cnt
    ,gmv
    ,gmv_local
    ,broad_order_cnt
    ,broad_gmv_amt_local
    ,revenue_usd
    ,ads_order_gmv_usd
    ,ads_order_cnt
    ,pclick_cnt
    ,porder_cnt_over_click
    ,porder_cnt_over_atc
    ,avg_imp_price
    ,price_v2
    ,pctr
    ,pcr
    ,pctr_50p
    ,pcr_50p
FROM fe_join_be_metrics_${grass_region_without_quote};
